mapper.select:
select assistant.id as assistant_message_id, user_msg.id as user_message_id, assistant.application_id as application_id, assistant.session_id as session_id, assistant.trace_id as trace_id, assistant.model_invocation_log_id as model_invocation_log_id, mil.status as invocation_status, case when assistant.model_invocation_log_id is null then 'knowledge-retrieval-fail-closed' when mil.status = 'FAILED' then 'model-invocation-failed' else 'spring-ai-chat-completion' end as decision_source, assistant.citation_count as citation_count, count(evidence.id) as evidence_count, provider.provider_code as provider_code, config.model_code as model_code, mil.input_tokens as input_tokens, mil.output_tokens as output_tokens, mil.latency_ms as latency_ms, assistant.created_at as created_at from app_chat_message assistant join app_chat_session session on session.id = assistant.session_id and session.tenant_id = assistant.tenant_id and session.deleted_at is null left join app_chat_message user_msg on user_msg.tenant_id = assistant.tenant_id and user_msg.session_id = assistant.session_id and user_msg.trace_id = assistant.trace_id and user_msg.role = 'user' left join mdl_invocation_log mil on mil.id = assistant.model_invocation_log_id and mil.tenant_id = assistant.tenant_id left join mdl_config config on config.id = mil.model_config_id and config.tenant_id = assistant.tenant_id and config.deleted_at is null left join mdl_provider provider on provider.id = config.provider_id and provider.tenant_id = assistant.tenant_id and provider.deleted_at is null left join app_chat_retrieval_evidence evidence on evidence.tenant_id = assistant.tenant_id and evidence.assistant_message_id = assistant.id where assistant.tenant_id = #{tenantId} and assistant.role = 'assistant' and assistant.trace_id is not null and user_msg.id is not null and session.application_id = #{applicationId} and session.user_id = #{userId}
and assistant.session_id = #{sessionId}
and assistant.trace_id = #{traceId}
and assistant.model_invocation_log_id = #{modelInvocationLogId}
and mil.status = #{invocationStatus}
group by assistant.id, user_msg.id, assistant.application_id, assistant.session_id, assistant.trace_id, assistant.model_invocation_log_id, mil.status, assistant.citation_count, provider.provider_code, config.model_code, mil.input_tokens, mil.output_tokens, mil.latency_ms, assistant.created_at order by assistant.created_at desc, assistant.id desc limit #{limit}

select assistant.id as assistant_message_id, user_msg.id as user_message_id, assistant.application_id as application_id, assistant.session_id as session_id, assistant.trace_id as trace_id, assistant.model_invocation_log_id as model_invocation_log_id, mil.status as invocation_status, user_msg.content as user_message_content, assistant.content as assistant_message_content, provider.provider_code as provider_code, config.model_code as model_code, case when assistant.model_invocation_log_id is null then 'knowledge-retrieval-fail-closed' when mil.status = 'FAILED' then 'model-invocation-failed' else 'spring-ai-chat-completion' end as decision_source, mil.input_tokens as input_tokens, mil.output_tokens as output_tokens, mil.latency_ms as latency_ms, mil.source_context as source_context, mil.source_resource_type as source_resource_type, cast(mil.source_resource_id as text) as source_resource_id, mil.error_code as error_code, mil.error_message as error_message, assistant.created_at as created_at from app_chat_message assistant join app_chat_session session on session.id = assistant.session_id and session.tenant_id = assistant.tenant_id and session.deleted_at is null left join app_chat_message user_msg on user_msg.tenant_id = assistant.tenant_id and user_msg.session_id = assistant.session_id and user_msg.trace_id = assistant.trace_id and user_msg.role = 'user' left join mdl_invocation_log mil on mil.id = assistant.model_invocation_log_id and mil.tenant_id = assistant.tenant_id left join mdl_config config on config.id = mil.model_config_id and config.tenant_id = assistant.tenant_id and config.deleted_at is null left join mdl_provider provider on provider.id = config.provider_id and provider.tenant_id = assistant.tenant_id and provider.deleted_at is null where assistant.tenant_id = #{tenantId} and assistant.id = #{assistantMessageId} and assistant.role = 'assistant' and session.application_id = #{applicationId}
and session.user_id = #{userId}
limit 1

select id, tenant_id, chat_message_id, knowledge_base_id, document_id, chunk_id, score, citation_text, created_at
from kb_citation_record
where tenant_id = #{tenantId}
  and chat_message_id = #{chatMessageId}
order by id asc

select id, tenant_id, assistant_message_id, trace_id, knowledge_base_id, document_id, chunk_id, score, retrieval_signal, index_version, created_at
from app_chat_retrieval_evidence
where tenant_id = #{tenantId}
  and assistant_message_id = #{assistantMessageId}
order by id asc
